∀ {ν : ℝ} {u₀ : Breakdown.Space → Breakdown.Space} {u : ℝ → Breakdown.Space → Breakdown.Space}
  {p : ℝ → Breakdown.Space → ℝ},
  Breakdown.IsSmoothSolution ν u₀ u p → ∀ t > 0, ∀ (x : Breakdown.Space), Breakdown.divergenceAt (u t) x = 0

