  {p : ℝ → Breakdown.Space → ℝ},
  Breakdown.IsSmoothSolution ν u₀ u p → ContDiffOn ℝ (↑⊤) (fun z => p z.1 z.2) (Set.Ici 0 ×ˢ Set.univ)

